#ifndef ZOVUTILS_NICE_LOGNAME_BACKEND_H
#define ZOVUTILS_NICE_LOGNAME_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <limits.h>
#include <sys/resource.h>
static inline int zov_logname_run(int argc,char**argv){for(int i=0;i<argc;i++){if(!strcmp(argv[i],"--help")){puts("Usage: logname [OPTION]\nPrint the name of the current user.\n  --help     display this help and exit\n  --version  output version information and exit");return 0;}if(!strcmp(argv[i],"--version")){puts("logname (zovutils) 0.10.23");return 0;}if(argv[i][0]=='-')fprintf(stderr,"logname: unrecognized option '%s'\nTry 'logname --help' for more information.\n",argv[i]);else fprintf(stderr,"logname: extra operand '%s'\nTry 'logname --help' for more information.\n",argv[i]);return 1;}char*p=getlogin();if(!p){fprintf(stderr,"logname: no login name\n");return 1;}puts(p);return 0;}
static inline int zov_nice_run(int argc,char**argv){int adjust=0,has_adjust=0,i=0;while(i<argc){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: nice [OPTION] [COMMAND [ARG]...]\nRun COMMAND with an adjusted niceness.\n  -n, --adjustment=N  add integer N to the priority\n      --help          display this help and exit\n      --version       output version information and exit");return 0;}if(!strcmp(a,"--version")){puts("nice (zovutils) 0.10.23");return 0;}if(!strcmp(a,"--")){i++;break;}if(!strcmp(a,"-n")||!strcmp(a,"--adjustment")){if(i+1>=argc){fprintf(stderr,"nice: option requires an argument -- 'n'\n");return 125;}char*e;long n=strtol(argv[i+1],&e,10);if(*e||n<INT_MIN||n>INT_MAX){fprintf(stderr,"nice: invalid adjustment '%s'\n",argv[i+1]);return 125;}adjust=(int)n;has_adjust=1;i+=2;continue;}if(!strncmp(a,"--adjustment=",13)){char*e;long n=strtol(a+13,&e,10);if(*e||n<INT_MIN||n>INT_MAX){fprintf(stderr,"nice: invalid adjustment '%s'\n",a+13);return 125;}adjust=(int)n;has_adjust=1;i++;continue;}if(a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"nice: unrecognized option '%s'\nTry 'nice --help' for more information.\n",a);return 125;}if(a[0]=='-'&&a[1]&&a[1]>='0'&&a[1]<='9'){char*e;long n=strtol(a,&e,10);if(*e||n<INT_MIN||n>INT_MAX){fprintf(stderr,"nice: invalid adjustment '%s'\n",a);return 125;}adjust=(int)n;has_adjust=1;i++;continue;}break;}if(i>=argc){errno=0;int p=getpriority(PRIO_PROCESS,0);if(p==-1&&errno)return 125;printf("%d\n",has_adjust?p+adjust:p);return 0;}errno=0;int current=getpriority(PRIO_PROCESS,0);if(current==-1&&errno){fprintf(stderr,"nice: cannot get niceness: %s\n",strerror(errno));return 125;}long wanted=(long)current+(has_adjust?adjust:10);if(wanted< -20)wanted=-20;if(wanted>19)wanted=19;if(setpriority(PRIO_PROCESS,0,(int)wanted)<0){fprintf(stderr,"nice: cannot set niceness: %s\n",strerror(errno));return 125;}execvp(argv[i],argv+i);fprintf(stderr,"nice: cannot run '%s': %s\n",argv[i],strerror(errno));return errno==ENOENT?127:126;}
#endif
